eseries_workload_read_latency{array=~"$Array",datacenter=~"$Datacenter",workload=~"$Workload"}
and on (datacenter, workload, array)
  topk(
    $TopResources,
    max by (datacenter, workload, array) (
      avg_over_time(
        eseries_workload_read_latency{array=~"$Array",datacenter=~"$Datacenter",workload=~"$Workload"}[3h] @ end()
      )
    )
  )

